package com.okip.controller;
import com.okip.dto.assessment.*; import com.okip.service.assessment.SelfAssessmentService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/self-assessments") public class SelfAssessmentController { private final SelfAssessmentService service; public SelfAssessmentController(SelfAssessmentService s){service=s;} @GetMapping("/my") public ResponseEntity<List<SelfAssessmentDTO>> my(){return ResponseEntity.ok(service.getMyAssessments());} @GetMapping("/{assessmentId}") public ResponseEntity<SelfAssessmentDTO> get(@PathVariable Long assessmentId){return ResponseEntity.ok(service.getAssessment(assessmentId));} @PostMapping("/{assessmentId}/start") public ResponseEntity<AssessmentResultDTO> start(@PathVariable Long assessmentId){return ResponseEntity.ok(service.start(assessmentId));} @PostMapping("/attempts/{attemptId}/submit") public ResponseEntity<AssessmentResultDTO> submit(@PathVariable Long attemptId,@RequestBody AssessmentSubmitRequestDTO request){return ResponseEntity.ok(service.submit(attemptId,request));} }
